import{_ as e,o as t,c as s,ag as a}from"./chunks/framework.C9sp7nFj.js";const k=JSON.parse('{"title":"Localization & RTL","description":"","frontmatter":{},"headers":[],"relativePath":"kit/localization.md","filePath":"kit/localization.md"}'),o={name:"kit/localization.md"};function n(l,i,r,d,h,c){return t(),s("div",null,[...i[0]||(i[0]=[a('<h1 id="localization-rtl" tabindex="-1">Localization &amp; RTL <a class="header-anchor" href="#localization-rtl" aria-label="Permalink to &quot;Localization &amp; RTL&quot;">​</a></h1><h2 id="ui-strings" tabindex="-1">UI strings <a class="header-anchor" href="#ui-strings" aria-label="Permalink to &quot;UI strings&quot;">​</a></h2><p>fewui&#39;s own strings (close buttons, empty states, aria labels) live under the <code>ui.*</code> namespace of your vue-i18n instance. The package ships <strong>Turkish</strong> and <strong>English</strong> packs:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(UiLib, { i18n, locales: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;tr&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;en&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] })</span></span></code></pre></div><ul><li>A language without a pack falls back to <strong>English</strong>. If you list it in <code>locales</code> (for example <code>[&#39;tr&#39;, &#39;en&#39;, &#39;de&#39;]</code>), the English strings are loaded under that locale so nothing renders as a raw key.</li><li>To translate fewui into another language, provide the <code>ui</code> messages yourself before installing the plugin; your translations are never overwritten:</li></ul><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> i18n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createI18n</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ locale: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;de&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, messages: { de: { ui: { dialog: { close: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Schließen&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } } } } })</span></span></code></pre></div><p><code>getUiMessages(&#39;tr&#39;)</code> returns a pack if you prefer to merge manually.</p><h2 id="dates" tabindex="-1">Dates <a class="header-anchor" href="#dates" aria-label="Permalink to &quot;Dates&quot;">​</a></h2><p>Date pickers format with <code>Intl</code>, using the active vue-i18n locale:</p><table tabindex="0"><thead><tr><th>Locale</th><th>Example</th></tr></thead><tbody><tr><td><code>tr</code></td><td>17 Kasım 2026</td></tr><tr><td><code>en</code> (also <code>en-US</code>)</td><td>17 November 2026</td></tr><tr><td>any other language the browser knows, e.g. <code>de</code></td><td>17. November 2026</td></tr><tr><td>empty or unknown</td><td>English</td></tr></tbody></table><h3 id="first-day-of-the-week" tabindex="-1">First day of the week <a class="header-anchor" href="#first-day-of-the-week" aria-label="Permalink to &quot;First day of the week&quot;">​</a></h3><p>The calendar starts the week on the locale&#39;s first day: Monday for <code>tr</code>, <code>de</code>, <code>en-GB</code>; Sunday for <code>en-US</code>. Override it per picker:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ui-date-picker</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> v-model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;date&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :week-start</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 0 = Sunday … 6 = Saturday --&gt;</span></span></code></pre></div><h2 id="right-to-left" tabindex="-1">Right-to-left <a class="header-anchor" href="#right-to-left" aria-label="Permalink to &quot;Right-to-left&quot;">​</a></h2><p>Set <code>dir=&quot;rtl&quot;</code> on <code>&lt;html&gt;</code> (or any ancestor). Components mirror automatically:</p><ul><li>Spacing, alignment, borders and corner radii use logical properties.</li><li>Popovers, selects, dropdowns and tours: <code>*-start</code> / <code>*-end</code> placements follow the text direction; <code>left</code> / <code>right</code> stay physical, as does <code>ui-sheet side=&quot;left|right&quot;</code>.</li><li>Arrow keys follow visual order in tabs, segments, chips, sliders, calendars, menus, the menubar and resizable handles.</li><li>Directional icons that fewui renders itself (back, next/previous, breadcrumb and submenu chevrons) are mirrored.</li></ul><p>For a directional icon in <strong>your</strong> template, add the <code>ui-icon--dir</code> class to the icon or to the button that renders it:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ui-button</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> prefix-icon</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;arrow-left&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ui-icon--dir&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Geri&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ui-button</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Icons that are not directional (refresh, external link, check) must not get the class.</p><h3 id="known-limits" tabindex="-1">Known limits <a class="header-anchor" href="#known-limits" aria-label="Permalink to &quot;Known limits&quot;">​</a></h3><ul><li>Verified in Chromium. Firefox and Safari have not been run in RTL.</li><li>Charts are not mirrored (the category axis keeps its order).</li><li>The phone country-code list can show <code>90+</code> instead of <code>+90</code> in RTL.</li><li><code>ui-pin</code> lays its cells out right-to-left in RTL; wrap it in <code>dir=&quot;ltr&quot;</code> if codes should always read left-to-right.</li><li>If <code>dir</code> is set only on a subtree, layers teleported to <code>&lt;body&gt;</code> are positioned correctly but their content does not inherit the direction.</li></ul>',21)])])}const g=e(o,[["render",n]]);export{k as __pageData,g as default};
